/**
 * Node 侧共用：基于 Readable/Writable 的 JSONL 信封通道。
 * Runtime / Mock 用 process.stdin/stdout；Electron Main 用子进程的 stdout/stdin。
 * 只做分帧与信封校验，不含业务语义。
 */
import type { Readable, Writable } from 'node:stream';

import { JsonlDecoder, encodeJsonLine, type JsonlDecodeResult } from '../jsonl';
import { parseEnvelope, type Envelope } from '../envelope';

export interface JsonlChannelOptions {
  input: Readable;
  output: Writable;
  maxLineBytes?: number;
  /** 收到无法解析的行时回调（默认忽略） */
  onDecodeError?: (result: Extract<JsonlDecodeResult, { ok: false }>) => void;
  /** 收到 JSON 但不是合法信封时回调（默认忽略） */
  onInvalidEnvelope?: (value: unknown, error: string) => void;
  /** 写入通道出错（对端已退出时的 EPIPE 等）；通道随即关闭 */
  onWriteError?: (error: Error) => void;
}

export type EnvelopeListener = (envelope: Envelope) => void;
export type CloseListener = (error?: Error) => void;

export class JsonlChannel {
  private readonly decoder: JsonlDecoder;
  private readonly listeners = new Set<EnvelopeListener>();
  private readonly closeListeners = new Set<CloseListener>();
  private closed = false;
  private readonly onData: (chunk: Buffer | string) => void;
  private readonly onEnd: () => void;
  private readonly onOutputError: (error: Error) => void;

  constructor(private readonly options: JsonlChannelOptions) {
    this.decoder = new JsonlDecoder({ maxLineBytes: options.maxLineBytes });
    this.onData = (chunk) => this.handle(this.decoder.push(chunk));
    this.onEnd = () => {
      this.handle(this.decoder.flush());
      this.markClosed();
    };
    // 对端进程崩溃的瞬间若还有请求在写，Node 会在写端 emit error(EPIPE)。
    // 没有监听器时它会抛到顶层，直接炸掉 Electron 主进程 / Runtime。
    this.onOutputError = (error) => {
      this.options.onWriteError?.(error);
      this.markClosed(error);
    };
    options.input.on('data', this.onData);
    options.input.on('end', this.onEnd);
    options.input.on('close', this.onEnd);
    options.output.on('error', this.onOutputError);
  }

  onMessage(listener: EnvelopeListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  onClose(listener: CloseListener): () => void {
    this.closeListeners.add(listener);
    return () => this.closeListeners.delete(listener);
  }

  send(envelope: Envelope): boolean {
    const { output } = this.options;
    if (this.closed || output.destroyed || !output.writable) return false;
    try {
      output.write(encodeJsonLine(envelope));
    } catch (error) {
      this.onOutputError(error instanceof Error ? error : new Error(String(error)));
      return false;
    }
    return true;
  }

  get isClosed(): boolean {
    return this.closed;
  }

  close(): void {
    this.options.input.off('data', this.onData);
    this.options.input.off('end', this.onEnd);
    this.options.input.off('close', this.onEnd);
    this.options.output.off('error', this.onOutputError);
    this.markClosed();
  }

  private markClosed(error?: Error) {
    if (this.closed) return;
    this.closed = true;
    for (const listener of this.closeListeners) listener(error);
  }

  private handle(results: JsonlDecodeResult[]) {
    for (const result of results) {
      if (!result.ok) {
        this.options.onDecodeError?.(result);
        continue;
      }
      const parsed = parseEnvelope(result.value);
      if (!parsed.ok) {
        this.options.onInvalidEnvelope?.(result.value, parsed.error);
        continue;
      }
      for (const listener of this.listeners) listener(parsed.value);
    }
  }
}

/** 递增 id 生成器（进程内唯一） */
export function createIdGenerator(prefix: string): () => string {
  let counter = 0;
  return () => `${prefix}_${Date.now().toString(36)}_${(++counter).toString(36)}`;
}

